# Owner(s): ["module: dynamo"]
# [MODULE DOC] Tests that Dynamo reconstructs Python objects correctly in generated bytecode:
# constant dict reconstruction (only changed keys versus everything), functional_call, ordered
# dicts, graph breaks inside wrapped functions, TMA descriptors, self-referential containers,
# opaque objects, and the bytecode-hook side-effect metadata. Many tests install a bytecode hook
# that inspects instructions. Runs the Dynamo test runner as a script.

import collections
import contextlib
import dis
import unittest

import torch
import torch._dynamo.test_case
from torch.testing._internal.common_utils import IS_FBCODE
from torch.testing._internal.inductor_utils import GPU_TYPE, HAS_GPU
from torch.utils._triton import (
    has_triton_experimental_host_tma,
    has_triton_tensor_descriptor_host_tma,
)


def _filter_instructions(instructions, opname):
    # [FUNCTION DOC] HELPER: Returns the list of instructions whose opname equals the given
    # name.
    return list(filter(lambda x: x.opname == opname, instructions))


class ReconstructTest(torch._dynamo.test_case.TestCase):
    # [CLASS DOC] Tests of how compiled bytecode reconstructs values, mostly by hooking the
    # generated bytecode and counting map-building instructions.
    @contextlib.contextmanager
    def register_bytecode_hook(self, fn):
        # [FUNCTION DOC] Context manager: resets Dynamo, registers a bytecode hook that passes
        # the disassembled instructions of the generated code to the given callable, and removes
        # the hook on exit even if an error occurred.
        def hook(code, out_code):
            # [FUNCTION DOC] HELPER: Bytecode hook: disassembles the output code, forwards
            # instructions to the callback and returns nothing (code unchanged).
            fn(list(dis.get_instructions(out_code)))
            return None

        torch._dynamo.reset()
        handle = torch._dynamo.convert_frame.register_bytecode_hook(hook)
        try:
            yield
        finally:
            handle.remove()

    def test_ConstDict_optimize_reconstruct(self):
        # [FUNCTION DOC] Mutating one new key of an input dict should reconstruct only that key:
        # the hook expects exactly one map-building instruction with one entry, and the
        # optimized result must equal the eager dict.
        """
        Emit code to reconstruct only the key that changed
        """

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting one map build instruction with a single
            # entry.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            self.assertEqual(len(build_map), 1)
            # reconstruct only d[40]
            self.assertEqual(build_map[0].argval, 1)

        def f(d, t):
            # [FUNCTION DOC] HELPER: Function under test: sets key 40 of the dict to t plus 1.
            d[40] = t + 1

        t = torch.randn(3, 4)
        d = {1: t}
        d_opt = d.copy()
        f(d, t)

        with self.register_bytecode_hook(hook):
            opt_f = torch.compile(f, backend="eager", fullgraph=True)
            opt_f(d_opt, t)
            self.assertEqual(d, d_opt)

    def _compile_and_capture_side_effects(self, fn, *args):
        # [FUNCTION DOC] Helper: compiles the function (fullgraph, eager) once while two
        # bytecode hooks are registered. The first returns a renamed copy of the output code;
        # the second records the side-effect source references and the has-side-effects flag of
        # the code it receives (the renamed one, since metadata is copied). Hooks are removed
        # afterwards; returns the captured mapping.
        """Compile fn and return side-effect metadata from bytecode hooks."""
        captured = {}

        def rewrite_hook(code, out_code):
            # [FUNCTION DOC] HELPER: Hook that returns the output code with its name changed.
            return out_code.replace(co_name=f"{out_code.co_name}_hooked")

        def inspect_hook(code, out_code):
            # [FUNCTION DOC] HELPER: Hook that stores side-effect refs and the has-side-effects
            # flag in the shared captured mapping.
            captured["refs"] = (
                torch._dynamo.convert_frame.get_compiled_code_side_effects(out_code)
            )
            captured["has_side_effects"] = (
                torch._dynamo.convert_frame.compiled_code_has_side_effects(out_code)
            )

        torch._dynamo.reset()
        rewrite_handle = torch._dynamo.convert_frame.register_bytecode_hook(
            rewrite_hook
        )
        inspect_handle = torch._dynamo.convert_frame.register_bytecode_hook(
            inspect_hook
        )
        try:
            torch.compile(fn, backend="eager", fullgraph=True)(*args)
        finally:
            inspect_handle.remove()
            rewrite_handle.remove()

        return captured

    def test_bytecode_hook_exposes_side_effect_refs(self):
        # [FUNCTION DOC] A function appending to an input list reports the reference to that
        # list as a side effect and the flag true; a pure function reports no references and
        # false.
        def mutating_fn(x, lst):
            # [FUNCTION DOC] HELPER: Appends x plus 1 to the list and returns x times 2.
            lst.append(x + 1)
            return x * 2

        def pure_fn(x):
            # [FUNCTION DOC] HELPER: Returns x times 2 with no side effects.
            return x * 2

        x = torch.randn(3)

        mutated = self._compile_and_capture_side_effects(mutating_fn, x, [])
        self.assertEqual(mutated["refs"], ("L['lst']",))
        self.assertTrue(mutated["has_side_effects"])

        pure = self._compile_and_capture_side_effects(pure_fn, x)
        self.assertEqual(pure["refs"], ())
        self.assertFalse(pure["has_side_effects"])

    def test_side_effect_refs_dict_mutation(self):
        # [FUNCTION DOC] Storing a value into an input dict is reported as a side effect on that
        # dict reference.
        def fn(x, d):
            # [FUNCTION DOC] HELPER: Stores x plus 1 under a key in the dict and returns x times
            # 2.
            d["result"] = x + 1
            return x * 2

        result = self._compile_and_capture_side_effects(fn, torch.randn(3), {})
        self.assertEqual(result["refs"], ("L['d']",))
        self.assertTrue(result["has_side_effects"])

    def test_side_effect_refs_tensor_in_container(self):
        # [FUNCTION DOC] Appending computed tensors to an external container is reported as a
        # side effect on the container (relevant to cudagraph handling).
        # Relevant to cudagraphs: a compiled function computes tensors and
        # stores them into an external container as a side effect.
        def fn(x, outputs):
            # [FUNCTION DOC] HELPER: Appends two computed tensors to the container and returns
            # x.
            y = x * 2
            z = x + 3
            outputs.append(y)
            outputs.append(z)
            return x

        result = self._compile_and_capture_side_effects(fn, torch.randn(4), [])
        self.assertEqual(result["refs"], ("L['outputs']",))
        self.assertTrue(result["has_side_effects"])

    def test_side_effect_refs_multiple_containers(self):
        # [FUNCTION DOC] Mutating a list and a dict reports exactly two side-effect references,
        # one for each.
        def fn(x, lst, d):
            # [FUNCTION DOC] HELPER: Appends to the list, stores into the dict, returns x.
            lst.append(x + 1)
            d["out"] = x * 2
            return x

        result = self._compile_and_capture_side_effects(fn, torch.randn(3), [], {})
        self.assertEqual(len(result["refs"]), 2)
        self.assertIn("L['lst']", result["refs"])
        self.assertIn("L['d']", result["refs"])
        self.assertTrue(result["has_side_effects"])

    def test_ConstDict_pop_reconstruct(self):
        # [FUNCTION DOC] Popping a key from the dict and then adding another forces full
        # reconstruction: one map-building instruction with two entries; the result must match
        # eager.
        """
        If something is pop'ed from the dict, we reconstruct everything
        """

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting one map build instruction with two entries.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            self.assertEqual(len(build_map), 1)
            # reconstruct everything
            self.assertEqual(build_map[0].argval, 2)

        def f(d, t):
            # [FUNCTION DOC] HELPER: Pops key 2, then sets key 40 to t plus 1.
            d.pop(2)
            d[40] = t + 1

        t = torch.randn(3, 4)
        d = {1: t, 2: t + 1}
        d_opt = d.copy()

        f(d, t)

        with self.register_bytecode_hook(hook):
            opt_f = torch.compile(f, backend="eager", fullgraph=True)
            opt_f(d_opt, t)
            self.assertEqual(d, d_opt)

    def test_ConstDict_popitem_reconstruct(self):
        # [FUNCTION DOC] Popitem on a two-entry dict is reconstructed as a whole dict; the hook
        # expects one map build with one entry (the remaining item) and the result must match
        # eager.
        """
        If something is pop'ed from the dict, we reconstruct everything
        """

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting one map build instruction with one entry.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            self.assertEqual(len(build_map), 1)
            # reconstruct everything
            self.assertEqual(build_map[0].argval, 1)

        def f(d, t):
            # [FUNCTION DOC] HELPER: Removes the last item from the dict.
            d.popitem()

        t = torch.randn(3, 4)
        d = {1: t, 2: t + 1}
        d_opt = d.copy()

        f(d, t)

        with self.register_bytecode_hook(hook):
            opt_f = torch.compile(f, backend="eager", fullgraph=True)
            opt_f(d_opt, t)
            self.assertEqual(d, d_opt)

    def test_ConstDict_popitem_reconstruct_graph_break(self):
        # [FUNCTION DOC] Same dict popitem scenario compiled without fullgraph (the call causes
        # a graph break); only checks the resulting dict equals eager.
        """
        If something is pop'ed from the dict, we reconstruct everything.
        Calling dict.popitem will graph break.
        """

        def f(d, t):
            # [FUNCTION DOC] HELPER: Removes the last item from the dict.
            d.popitem()

        t = torch.randn(3, 4)
        d = {1: t, 2: t + 1}
        d_opt = d.copy()

        f(d, t)

        opt_f = torch.compile(backend="eager")(f)
        opt_f(d_opt, t)
        self.assertEqual(d, d_opt)

