    def test_ConstDict_get_reconstruct(self):
        # [FUNCTION DOC] Reading with dict get and then assigning one key rebuilds only one
        # entry: one map build with one entry.
        # KNOWN ISSUE: the hook checks that the integer 123 is not among the load-constant
        # instruction objects, which compares an int against instruction records and so can
        # never fail.
        """
        dict.get shouldn't affect anything
        """

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting one map build with one entry and that no
            # load constant matches 123.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            self.assertEqual(len(build_map), 1)
            self.assertEqual(build_map[0].argval, 1)
            load_const = _filter_instructions(instructions, "LOAD_CONST")
            self.assertNotIn(123, load_const)

        def f(d, t):
            # [FUNCTION DOC] HELPER: Sets key 456 to its existing value plus t.
            d[456] = d.get(456) + t

        t = torch.randn(3, 4)
        d = {123: t, 456: t + 1}
        d_opt = d.copy()

        f(d, t)

        with self.register_bytecode_hook(hook):
            opt_f = torch.compile(f, backend="eager", fullgraph=True)
            opt_f(d_opt, t)
            self.assertEqual(d, d_opt)

    def test_ConstDict_clear_reconstruct(self):
        # [FUNCTION DOC] After clear and one new key, the hook expects a single map build with
        # one entry; the result must match eager.
        """
        If dict.clear() is used, we reconstruct everything
        """

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting one map build instruction with one entry.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            self.assertEqual(len(build_map), 1)
            # reconstruct everything
            self.assertEqual(build_map[0].argval, 1)

        def f(d, t):
            # [FUNCTION DOC] HELPER: Clears the dict then sets key 3 to t plus 3.
            d.clear()
            d[3] = t + 3

        t = torch.randn(3, 4)
        d = {1: t, 2: t + 1}
        d_opt = d.copy()

        f(d, t)

        with self.register_bytecode_hook(hook):
            opt_f = torch.compile(f, backend="eager", fullgraph=True)
            opt_f(d_opt, t)
            self.assertEqual(d, d_opt)

    def test_create_dict_reconstruct(self):
        # [FUNCTION DOC] A dict created inside the compiled function and returned is fully
        # constructed: one map build with two entries; result matches eager.
        """
        If dict is created inside a function, everything needs to be reconstructed
        """

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting one map build instruction with two entries.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            self.assertEqual(len(build_map), 1)
            # reconstruct everything
            self.assertEqual(build_map[0].argval, 2)

        def f(t):
            # [FUNCTION DOC] HELPER: Returns a new dict with two tensor values.
            return {1: t, 2: t + 1}

        t = torch.randn(3, 4)
        d = f(t)

        with self.register_bytecode_hook(hook):
            opt_f = torch.compile(f, backend="eager", fullgraph=True)
            d_opt = opt_f(t)
            self.assertEqual(d, d_opt)

    @unittest.skipIf(
        IS_FBCODE, "capturing functional_call is not enabled by default in FB_CODE"
    )
    def test_functional_call_reconstruct(self):
        # [FUNCTION DOC] Skipped in FB code. A functional_call with a parameter dict made inside
        # the function must not emit any map-building instruction; output must equal the manual
        # linear computation.
        """
        PyTorch shouldn't codegen any key/value when functional_call is used
        """

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting no map build instructions.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            # don't reconstruct anything
            self.assertEqual(len(build_map), 0)

        m = torch.nn.Linear(3, 3)
        new_bias = torch.randn(3)
        new_weight = torch.randn(3, 3)

        def fn(new_weight, new_bias, x):
            # [FUNCTION DOC] HELPER: Calls functional call on the outer module with a new
            # weight/bias mapping and input.
            return torch.func.functional_call(
                m, {"weight": new_weight, "bias": new_bias}, x
            )

        x = torch.randn(2, 3)
        expected = torch.nn.functional.linear(x, new_weight, new_bias)
        with self.register_bytecode_hook(hook):
            opt_fn = torch.compile(fn, backend="eager", fullgraph=True)
            got = opt_fn(new_weight, new_bias, x)
            self.assertEqual(expected, got)

    @unittest.skipIf(
        IS_FBCODE, "capturing functional_call is not enabled by default in FB_CODE"
    )
    def test_functional_call_reconstruct_2(self):
        # [FUNCTION DOC] Skipped in FB code. functional_call on a nested module-dict model with
        # its state dict emits no map-building instruction; output matches eager.
        """
        PyTorch shouldn't codegen any key/value when functional_call is used
        """

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting no map build instructions.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            # don't reconstruct anything
            self.assertEqual(len(build_map), 0)

        class DummyModule(torch.nn.Module):
            # [CLASS DOC] HELPER: Test module holding four levels of nested module dictionaries
            # ending in a bias-free 10 by 10 linear layer.
            def __init__(self):
                # [FUNCTION DOC] HELPER: Builds the nested module dictionaries.
                super().__init__()
                self.a = torch.nn.ModuleDict(
                    {
                        "b": torch.nn.ModuleDict(
                            {
                                "c": torch.nn.ModuleDict(
                                    {
                                        "d": torch.nn.ModuleDict(
                                            {"e": torch.nn.Linear(10, 10, bias=False)}
                                        )
                                    }
                                )
                            }
                        )
                    }
                )

            def forward(self, x):
                # [FUNCTION DOC] HELPER: Applies the innermost linear layer.
                return self.a.b.c.d.e(x)

        model = DummyModule()

        def fn(model, states, x):
            # [FUNCTION DOC] HELPER: Runs functional call of the model with the given state
            # mapping.
            return torch.func.functional_call(model, states, x)

        x = torch.randn(2, 3)
        states = model.state_dict()
        x = torch.randn(10, 10)
        expected = fn(model, states, x)
        with self.register_bytecode_hook(hook):
            opt_fn = torch.compile(fn, backend="eager", fullgraph=True)
            got = opt_fn(model, states, x)
            self.assertEqual(expected, got)

    def test_ordered_dict_no_reconstruct_without_mutation(self):
        # [FUNCTION DOC] An ordered dict that is only read, not mutated, is not reconstructed:
        # the hook expects zero map builds and the result is 2.0.
        """Sourced OrderedDict should not emit BUILD_MAP when not mutated."""

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook asserting no map build instructions.
            build_map = _filter_instructions(instructions, "BUILD_MAP")
            self.assertEqual(len(build_map), 0)

        def fn(od, x):
            # [FUNCTION DOC] HELPER: Adds the value under key a to x.
            return x + od["a"]

        od = collections.OrderedDict(a=1, b=2)
        with self.register_bytecode_hook(hook):
            opt_fn = torch.compile(fn, backend="eager", fullgraph=True)
            got = opt_fn(od, torch.tensor(1.0))
            self.assertEqual(got, torch.tensor(2.0))

    def test_graph_break_in_wrapped_user_function(self):
        # [FUNCTION DOC] A graph break inside a function wrapped by no-grad, called from
        # compiled code, must reconstruct the wrapper so grad mode is off inside the wrapped
        # function and restored afterwards; the result is input plus 3.
        def fn(x):
            # [FUNCTION DOC] HELPER: Adds 1, graph breaks, asserts compiling and grad disabled,
            # adds 2.
            x = x + 1
            torch._dynamo.graph_break()
            assert torch.compiler.is_compiling()  # noqa: S101
            assert not torch.is_grad_enabled()  # noqa: S101
            return x + 2

        @torch.compile(backend="eager")
        def gn(x):
            # [FUNCTION DOC] HELPER: Compiled caller: runs the no-grad wrapped function, then
            # asserts compiling and grad enabled.
            x = torch.no_grad()(fn)(x)
            # reconstruction failure would cause a skipped frame
            assert torch.compiler.is_compiling()  # noqa: S101
            assert torch.is_grad_enabled()  # noqa: S101
            return x

        inp = torch.randn(3)
        self.assertEqual(gn(inp), inp + 3)

    def test_graph_break_in_wrapped_user_method(self):
        # [FUNCTION DOC] Same as the wrapped function test but the wrapped callable is a bound
        # method stored on an object; checks reconstruction of the wrapper after the graph break
        # and that the result is input plus 3.
        class Foo:
            # [CLASS DOC] HELPER: Simple object with two integer attributes and a method that
            # breaks the graph.
            def __init__(self):
                # [FUNCTION DOC] HELPER: Sets attributes a=1 and b=2.
                self.a = 1
                self.b = 2

            def fn(self, x):
                # [FUNCTION DOC] HELPER: Adds a, graph breaks, asserts compiling and grad
                # disabled, adds b.
                x = x + self.a
                torch._dynamo.graph_break()
                assert torch.compiler.is_compiling()  # noqa: S101
                assert not torch.is_grad_enabled()  # noqa: S101
                return x + self.b

        obj = Foo()

        @torch.compile(backend="eager")
        def gn(x):
            # [FUNCTION DOC] HELPER: Compiled caller: replaces the method by a no-grad wrapped
            # one, calls it, asserts compiling and grad enabled.
            obj.fn = torch.no_grad()(obj.fn)
            x = obj.fn(x)
            # reconstruction failure would cause a skipped frame
            assert torch.compiler.is_compiling()  # noqa: S101
            assert torch.is_grad_enabled()  # noqa: S101
            return x

        inp = torch.randn(3)
        self.assertEqual(gn(inp), inp + 3)

    def test_graph_break_in_wrapped_nested_function(self):
        # [FUNCTION DOC] Same check when the no-grad decorated function is defined nested inside
        # the compiled function and closes over local values.
        @torch.compile(backend="eager")
        def gn(x):
            # [FUNCTION DOC] HELPER: Compiled function defining and calling a nested no-grad
            # function with a graph break, then asserting compiling and grad enabled.
            a = 1
            b = 2

            @torch.no_grad()
            def fn(x):
                # [FUNCTION DOC] HELPER: Nested no-grad function: adds a, graph breaks, asserts
                # compiling and grad disabled, adds b.
                x = x + a
                torch._dynamo.graph_break()
                assert torch.compiler.is_compiling()  # noqa: S101
                assert not torch.is_grad_enabled()  # noqa: S101
                return x + b

            x = fn(x)
            # reconstruction failure would cause a skipped frame
            assert torch.compiler.is_compiling()  # noqa: S101
            assert torch.is_grad_enabled()  # noqa: S101
            return x

        inp = torch.randn(3)
        self.assertEqual(gn(inp), inp + 3)

    def test_graph_break_in_wrapped_skipped_function(self):
        # [FUNCTION DOC] Checks the test helper function is classified as a skipped function by
        # the trace rules, then runs a graph break in a function passed through that skipped
        # helper wrapped in no-grad, expecting the result input plus 3 and correct grad state.
        from torch._dynamo import trace_rules
        from torch._dynamo.testing import _skipped_function_for_test_reconstruct
        from torch._dynamo.variables import SkipFunctionVariable

        self.assertIs(
            trace_rules.lookup(_skipped_function_for_test_reconstruct),
            SkipFunctionVariable,
        )

        def fn(x):
            # [FUNCTION DOC] HELPER: Adds 1, graph breaks, asserts compiling and grad disabled,
            # adds 2.
            x = x + 1
            torch._dynamo.graph_break()
            assert torch.compiler.is_compiling()  # noqa: S101
            assert not torch.is_grad_enabled()  # noqa: S101
            return x + 2

        @torch.compile(backend="eager")
        def gn(x):
            # [FUNCTION DOC] HELPER: Compiled caller: calls the skipped helper with the function
            # under no-grad, then asserts compiling and grad enabled.
            x = torch.no_grad()(_skipped_function_for_test_reconstruct)(fn, x)
            # reconstruction failure would cause a skipped frame
            assert torch.compiler.is_compiling()  # noqa: S101
            assert torch.is_grad_enabled()  # noqa: S101
            return x

        inp = torch.randn(3)
        self.assertEqual(gn(inp), inp + 3)

    @unittest.skipIf(not HAS_GPU, "requires GPU and Triton")
    @unittest.skipIf(
        not has_triton_experimental_host_tma(),
        "Test requires triton.tools.experimental_descriptor API",
    )
    def test_tma_experimental_reconstruct(self):
        # [FUNCTION DOC] Skipped without a GPU and Triton or without the experimental host TMA
        # API. Creates a TMA descriptor inside a compiled function and checks the returned
        # descriptor matches the eager one.
        import triton

        def create_tma(tensor):
            # [FUNCTION DOC] HELPER: Builds a 2D TMA descriptor for the tensor and returns the
            # tensor plus 1 together with the descriptor.
            tma = triton.tools.experimental_descriptor.create_2d_tma_descriptor(
                tensor.data_ptr(),
                tensor.size(0),
                tensor.size(1),
                32,
                32,
                tensor.element_size(),
            )
            return tensor + 1, tma

        x = torch.randn(128, 128, device=GPU_TYPE)

        ref = create_tma(x)
        res = torch.compile(create_tma, backend="eager")(x)
        self.assertEqual(ref[1].desc, res[1].desc)

    @unittest.skipIf(not HAS_GPU, "requires GPU and Triton")
    @unittest.skipIf(
        not has_triton_tensor_descriptor_host_tma(),
        "Test requires triton.tools.tensor_descriptor API",
    )
    def test_tma_stable_reconstruct(self):
        # [FUNCTION DOC] Skipped without a GPU and Triton or without the stable tensor-
        # descriptor API. Creates a descriptor inside a compiled function and checks the result
        # equals eager.
        import triton

        def create_tma(tensor):
            # [FUNCTION DOC] HELPER: Builds a tensor descriptor with 32 by 32 block and returns
            # the tensor plus 1 with the descriptor.
            tma = triton.tools.tensor_descriptor.TensorDescriptor.from_tensor(
                tensor,
                [32, 32],
            )
            return tensor + 1, tma

        x = torch.randn(128, 128, device=GPU_TYPE)

        ref = create_tma(x)
        res = torch.compile(create_tma, backend="eager")(x)
        self.assertEqual(ref, res)

    def test_self_referential_sourceful(self):
        # [FUNCTION DOC] A list containing a tuple that refers back to the list is passed as
        # input and printed (a graph break with it on the stack); compiled and eager results
        # must be equal.
        l = []
        l.append((0, l))

        def fn(x, l):
            # [FUNCTION DOC] HELPER: Adds 1, prints the list, returns x plus the list length.
            x = x + 1
            # self-referential object on the stack during a graph break
            print(l)
            return x + len(l)

        opt_fn = torch.compile(fn, backend="eager")
        inp = torch.randn(3)
        self.assertEqual(fn(inp, l), opt_fn(inp, l))

    def test_self_referential_sourceless(self):
        # [FUNCTION DOC] Builds self-referential list, deque, dict, ordered dict and default
        # dict inside compiled functions (with and without a graph break after printing) and
        # asserts the returned container contains itself.
        @torch.compile(backend="eager")
        def fn(x, construct_fn):
            # [FUNCTION DOC] HELPER: Compiled with graph break: builds a container, adds to x,
            # prints, adds again, asserts compiling, returns it.
            l = construct_fn()

            x += 1
            print(l)
            x += 1
            # if reconstruction failed on the graph break, we should error here
            assert torch.compiler.is_compiling()  # noqa: S101
            return l

        @torch.compile(backend="eager", fullgraph=True)
        def fn2(x, construct_fn):
            # [FUNCTION DOC] HELPER: Fullgraph version: builds a container with the factory,
            # adds to x, returns it.
            l = construct_fn()
            x += 1
            return l

        def construct_list():
            # [FUNCTION DOC] HELPER: Returns a list that contains itself.
            l = []
            l.append(l)
            return l

        out = fn(torch.ones(3), construct_list)
        self.assertIs(out[0], out)
        out = fn2(torch.ones(3), construct_list)
        self.assertIs(out[0], out)

        def construct_deque():
            # [FUNCTION DOC] HELPER: Returns a deque that contains itself.
            d = collections.deque()
            d.append(d)
            return d

        out = fn(torch.ones(3), construct_deque)
        self.assertIs(out[0], out)
        out = fn2(torch.ones(3), construct_deque)
        self.assertIs(out[0], out)

        def construct_dict():
            # [FUNCTION DOC] HELPER: Returns a dict that contains itself under key 0.
            d = {}
            d[0] = d
            return d

        out = fn(torch.ones(3), construct_dict)
        self.assertIs(out[0], out)
        out = fn2(torch.ones(3), construct_dict)
        self.assertIs(out[0], out)

        def construct_ordereddict():
            # [FUNCTION DOC] HELPER: Returns an ordered dict that contains itself under key 0.
            d = collections.OrderedDict()
            d[0] = d
            return d

        out = fn(torch.ones(3), construct_ordereddict)
        self.assertIs(out[0], out)
        out = fn2(torch.ones(3), construct_ordereddict)
        self.assertIs(out[0], out)

        def construct_defaultdict():
            # [FUNCTION DOC] HELPER: Returns a default dict that contains itself under key 0.
            d = collections.defaultdict()
            d[0] = d
            return d

        out = fn(torch.ones(3), construct_defaultdict)
        self.assertIs(out[0], out)
        out = fn2(torch.ones(3), construct_defaultdict)
        self.assertIs(out[0], out)

    def test_non_self_referential_list_is_not_stored(self):
        # [FUNCTION DOC] Checks a list that is not self-referential is not stored in a temporary
        # local during reconstruction, while a self-referential one is: the hook raises
        # AssertionError when a build-list instruction is followed by duplicate-top and a local
        # store; the first function must pass and the second must raise with that message.
        # Non-self referential list should not be stored as a temporary variable.
        def fn(x):
            # [FUNCTION DOC] HELPER: Returns x and a constant list.
            l = [1, 2, 3]
            return x, l

        def gn(x):
            # [FUNCTION DOC] HELPER: Returns x and a list that has been appended to itself.
            l = [1, 2, 3]
            l.append(l)
            return x, l

        def hook(instructions: list[dis.Instruction]):
            # [FUNCTION DOC] HELPER: Hook that scans for build-list followed by duplicate-top
            # and store-fast, and raises an assertion if found.
            from torch._dynamo.bytecode_transformation import create_dup_top

            dup_top_inst = create_dup_top().opname
            for i, inst in enumerate(instructions):
                if inst.opname == "BUILD_LIST" and i + 2 < len(instructions):
                    assert not (  # noqa: S101
                        instructions[i + 1].opname == dup_top_inst
                        and instructions[i + 2].opname == "STORE_FAST"
                    ), "found list stored as tmp"

        with self.register_bytecode_hook(hook):
            opt_fn = torch.compile(fn, backend="eager", fullgraph=True)
            opt_fn(torch.ones(3))
            with self.assertRaisesRegex(AssertionError, "found list stored as tmp"):
                opt_gn = torch.compile(gn, backend="eager", fullgraph=True)
                opt_gn(torch.ones(3))

    def test_opaque_reference_as_python_constant(self):
        # [FUNCTION DOC] Registers a reference-type opaque custom class whose truth value is
        # true, and checks a compiled fullgraph function branching on an instance works, adding
        # one to the tensor (as python constant must succeed).
        """TSOV.as_python_constant must succeed for reference-type opaque
        objects. Without this, __eq__ between two opaque objects graph breaks.
        """
        import torch._custom_class_base
        import torch._library.opaque_object

        class Config(torch._custom_class_base.CustomClassBase):
            # [CLASS DOC] HELPER: Custom class base subclass holding a value, with truthiness
            # always true and equality and hash based on the value.
            def __init__(self, v):
                # [FUNCTION DOC] HELPER: Stores the value.
                self.v = v

            def __bool__(self):
                # [FUNCTION DOC] HELPER: Always true.
                return True

            def __eq__(self, other):
                # [FUNCTION DOC] HELPER: Equal if the other is the same class with equal value.
                return isinstance(other, Config) and self.v == other.v

            def __hash__(self):
                # [FUNCTION DOC] HELPER: Hash of the value.
                return hash(self.v)

        torch._library.opaque_object.register_custom_class(Config, typ="symbolic")

        cfg = Config(42)

        def fn(x, cfg):
            # [FUNCTION DOC] HELPER: Returns x plus 1 if the object is truthy, else x.
            if cfg:
                return x + 1
            return x

        opt = torch.compile(fn, backend="eager", fullgraph=True)
        result = opt(torch.ones(4), cfg)
        self.assertEqual(result, torch.ones(4) + 1)

    def test_call_once_guard_allows_super_delegation(self):
        # [FUNCTION DOC] Checks the call-once guard keys on the object and method identity, so a
        # subclass method delegating to its parent version of as_python_constant returns 42
        # without a false self-referential error, and is_python_constant is true.
        """_add_call_once_guard must key on (id(self), id(original_method))
        so that super().as_python_constant() between VT subclasses is not
        mistaken for a self-referential call.
        """
        from torch._dynamo.variables.base import VariableTracker

        class _Parent(VariableTracker):
            # [CLASS DOC] HELPER: Variable tracker whose python constant is 42.
            def as_python_constant(self):
                # [FUNCTION DOC] HELPER: Returns 42.
                return 42

        class _Child(_Parent):
            # [CLASS DOC] HELPER: Subclass that delegates python constant to its parent.
            def as_python_constant(self):
                # [FUNCTION DOC] HELPER: Returns the parent constant.
                return super().as_python_constant()

        child = _Child()
        # With name-based keying, _Child and _Parent share the same key
        # (id(self), "as_python_constant"), causing a false
        # AsPythonConstantNotImplementedError("self-referential").
        self.assertEqual(child.as_python_constant(), 42)
        self.assertTrue(child.is_python_constant())


